'use strict';

// MODULES //

var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );


// FUNCTIONS //

/**
* Validates the triangle and leading prefix dimensions.
*
* @private
* @param {string} uplo - triangle
* @param {NonNegativeInteger} NCOLS - prefix size
* @throws {TypeError} invalid triangle
* @throws {RangeError} invalid prefix size
* @returns {integer} triangle enum
*/
function validate( uplo, NCOLS ) {
	if ( uplo !== 'upper' && uplo !== 'lower' ) {
		throw new TypeError( 'invalid argument. Triangle must be upper or lower.' );
	}
	if ( !isSafeInteger( NCOLS ) || NCOLS < 0 ) {
		throw new RangeError( 'invalid argument. NCOLS must be a nonnegative safe integer.' );
	}
	return ( uplo === 'upper' ) ? 121 : 122;
}


// MAIN //

/**
* Creates the public main and ndarray interfaces.
*
* @private
* @param {Function} base - numerical kernel
* @returns {Function} public interfaces
*/
function factory( base ) {
	setReadOnly( dlaPorpvgrw, 'ndarray', ndarray );
	return dlaPorpvgrw;

	/**
	* Computes the reciprocal Cholesky pivot-growth factor.
	*
	* @private
	* @param {string} order - row-major or column-major
	* @param {string} uplo - upper or lower
	* @param {NonNegativeInteger} NCOLS - leading square order
	* @param {Float64Array} A - original matrix
	* @param {PositiveInteger} LDA - leading dimension of A
	* @param {Float64Array} AF - supplied Cholesky factor
	* @param {PositiveInteger} LDAF - leading dimension of AF
	* @param {Float64Array} WORK - 2*NCOLS scratch entries
	* @throws {TypeError} invalid order or triangle
	* @throws {RangeError} invalid dimension or leading dimension
	* @returns {number} reciprocal pivot growth
	*/
	function dlaPorpvgrw( order, uplo, NCOLS, A, LDA, AF, LDAF, WORK ) {
		var sa1;
		var sa2;
		var sf1;
		var sf2;
		var u;

		if ( order !== 'row-major' && order !== 'column-major' ) {
			throw new TypeError( 'invalid argument. Order must be row-major or column-major.' );
		}
		u = validate( uplo, NCOLS );
		if ( NCOLS === 0 ) {
			return 1.0;
		}
		if ( !isSafeInteger( LDA ) || LDA < NCOLS || !isSafeInteger( LDAF ) || LDAF < NCOLS ) {
			throw new RangeError( 'invalid argument. Leading dimensions must be safe integers at least NCOLS.' );
		}
		if ( order === 'column-major' ) {
			sa1 = 1;
			sa2 = LDA;
			sf1 = 1;
			sf2 = LDAF;
		} else {
			sa1 = LDA;
			sa2 = 1;
			sf1 = LDAF;
			sf2 = 1;
		}
		return base( u, NCOLS, A, sa1, sa2, 0, AF, sf1, sf2, 0, WORK, 1, 0 );
	}

	/**
	* Computes reciprocal Cholesky pivot growth using alternative indexing.
	*
	* @private
	* @param {string} uplo - upper or lower
	* @param {NonNegativeInteger} NCOLS - leading square order
	* @param {Float64Array} A - original matrix
	* @param {integer} strideA1 - row stride of A
	* @param {integer} strideA2 - column stride of A
	* @param {integer} offsetA - offset of A
	* @param {Float64Array} AF - supplied factor
	* @param {integer} strideAF1 - row stride of AF
	* @param {integer} strideAF2 - column stride of AF
	* @param {integer} offsetAF - offset of AF
	* @param {Float64Array} WORK - scratch storage
	* @param {NonZeroInteger} strideWork - scratch stride
	* @param {integer} offsetWork - scratch offset
	* @throws {TypeError} invalid triangle
	* @throws {RangeError} invalid dimension or integer metadata
	* @returns {number} reciprocal pivot growth
	*/
	function ndarray( uplo, NCOLS, A, strideA1, strideA2, offsetA, AF, strideAF1, strideAF2, offsetAF, WORK, strideWork, offsetWork ) { // eslint-disable-line max-params
		var metadata;
		var u;
		var i;

		u = validate( uplo, NCOLS );
		if ( NCOLS === 0 ) {
			return 1.0;
		}
		metadata = [ strideA1, strideA2, offsetA, strideAF1, strideAF2, offsetAF, strideWork, offsetWork ];
		for ( i = 0; i < metadata.length; i++ ) {
			if ( !isSafeInteger( metadata[ i ] ) ) {
				throw new RangeError( 'invalid argument. Strides and offsets must be safe integers.' );
			}
		}
		if ( strideWork === 0 ) {
			throw new RangeError( 'invalid argument. Workspace stride must be nonzero.' );
		}
		return base( u, NCOLS, A, strideA1, strideA2, offsetA, AF, strideAF1, strideAF2, offsetAF, WORK, strideWork, offsetWork );
	}
}


// EXPORTS //

module.exports = factory;
